import sys

class SegTree:
    def __init__(self, n):
        self.n = n
        self.size = 1
        while self.size < n:
            self.size <<= 1
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)
        # Initialize leaves for indices 1..n with their own index
        for i in range(n):
            self.tree[self.size + i] = i + 1
        # Remaining leaves keep 0 (safe because queries have L >= 1)
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = max(self.tree[2 * i], self.tree[2 * i + 1])

    def _push(self, node, l, r):
        if self.lazy[node] != 0:
            if l != r:
                left = 2 * node
                right = left + 1
                self.tree[left] += self.lazy[node]
                self.lazy[left] += self.lazy[node]
                self.tree[right] += self.lazy[node]
                self.lazy[right] += self.lazy[node]
            self.lazy[node] = 0

    def _range_add(self, node, nl, nr, l, r, val):
        if r < nl or nr < l:
            return
        if l <= nl and nr <= r:
            self.tree[node] += val
            self.lazy[node] += val
            return
        self._push(node, nl, nr)
        mid = (nl + nr) // 2
        self._range_add(2 * node, nl, mid, l, r, val)
        self._range_add(2 * node + 1, mid + 1, nr, l, r, val)
        self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])

    def range_add(self, l, r, val):
        if l > r:
            return
        self._range_add(1, 1, self.size, l, r, val)

    def find_first_ge(self, x):
        if self.tree[1] < x:
            return None
        node = 1
        nl = 1
        nr = self.size
        while nl != nr:
            self._push(node, nl, nr)
            mid = (nl + nr) // 2
            if self.tree[2 * node] >= x:
                node = 2 * node
                nr = mid
            else:
                node = 2 * node + 1
                nl = mid + 1
        return nl

    def point_query(self, idx):
        node = 1
        nl = 1
        nr = self.size
        while nl != nr:
            self._push(node, nl, nr)
            mid = (nl + nr) // 2
            if idx <= mid:
                node = 2 * node
                nr = mid
            else:
                node = 2 * node + 1
                nl = mid + 1
        return self.tree[node]

def main():
    import sys
    input = sys.stdin.readline
    N = int(input())
    intervals = []
    for _ in range(N):
        L, R = map(int, input().split())
        intervals.append((L, R))
    Q = int(input())
    queries = [int(input()) for _ in range(Q)]

    max_initial = max(queries) if queries else 0
    max_R = max((R for _, R in intervals), default=0)
    max_possible = max(max_initial, max_R) + N + 1
    n = max_possible
    if n < 1:
        n = 1

    seg = SegTree(n)

    for L, R in intervals:
        a = seg.find_first_ge(L)
        if a is None:
            continue
        b_idx = seg.find_first_ge(R + 1)
        if b_idx is None:
            b = n
        else:
            b = b_idx - 1
        if a <= b:
            seg.range_add(a, b, 1)

    out = []
    for X in queries:
        out.append(str(seg.point_query(X)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

import sys

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(n):
                    Ci[j] = (Ci[j] + aik * Bk[j]) % mod
    return C

def mat_pow(F, power, mod):
    n = len(F)
    # Identity matrix
    res = [[0]*n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1
    while power > 0:
        if power & 1:
            res = mat_mul(res, F, mod)
        F = mat_mul(F, F, mod)
        power >>= 1
    return res

def solve():
    input = sys.stdin.readline
    N, p = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(N)]

    if p == 2:
        val = N % 2
        for i in range(N):
            print(' '.join([str(val)] * N))
        return

    mod = p
    K = 0
    zeros = []
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1
                zeros.append((i, j))

    sign = 1 if K % 2 == 0 else mod - 1

    # Build F: nonzero entries of A, zero elsewhere
    F = [[A[i][j] if A[i][j] != 0 else 0 for j in range(N)] for i in range(N)]

    # Compute F^p mod p
    P = mat_pow(F, p, mod)

    # Build extra matrix E
    E = [[0]*N for _ in range(N)]
    for (i, j) in zeros:
        if i == j:
            # self-loop zero
            for y in range(N):
                if F[i][y] != 0:
                    E[i][y] = (E[i][y] + F[i][y]) % mod
            for x in range(N):
                if F[x][i] != 0:
                    E[x][i] = (E[x][i] + F[x][i]) % mod
        elif p == 3:
            # non-self-loop zero, only p=3 contributes
            if F[j][i] != 0:
                E[i][j] = (E[i][j] + F[j][i]) % mod

    T = [[(P[i][j] + E[i][j]) % mod for j in range(N)] for i in range(N)]
    S = [[(sign * T[i][j]) % mod for j in range(N)] for i in range(N)]

    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(map(str, S[i])))
    print('\n'.join(out_lines))

if __name__ == "__main__":
    solve()

