from typing import List

class Node:
    __slots__ = ('sum', 'pref', 'suff', 'best')
    def __init__(self, sum=0, pref=0, suff=0, best=0):
        self.sum = sum
        self.pref = pref
        self.suff = suff
        self.best = best
    @staticmethod
    def combine(left, right):
        res = Node()
        res.sum = left.sum + right.sum
        res.pref = max(left.pref, left.sum + right.pref)
        res.suff = max(right.suff, right.sum + left.suff)
        res.best = max(left.best, right.best, left.suff + right.pref)
        return res

class SegTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        self.data = [Node() for _ in range(2 * self.size)]
        # Build leaves
        for i in range(self.n):
            self.data[self.size + i] = Node(arr[i], arr[i], arr[i], arr[i])
        for i in range(self.size - 1, 0, -1):
            self.data[i] = Node.combine(self.data[2*i], self.data[2*i+1])
    def update(self, idx, value):
        i = self.size + idx
        self.data[i] = Node(value, value, value, value)
        i //= 2
        while i:
            self.data[i] = Node.combine(self.data[2*i], self.data[2*i+1])
            i //= 2
    def query(self):
        return self.data[1].best

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0
        # Build segment tree
        seg = SegTree(nums)
        original_best = seg.query()
        ans = original_best
        # Build map from value to indices
        val_to_indices = {}
        for i, v in enumerate(nums):
            val_to_indices.setdefault(v, []).append(i)
        # For each unique value
        for v, indices in val_to_indices.items():
            if len(indices) == n:
                # Removing this would empty the array
                continue
            # Set to 0
            for i in indices:
                seg.update(i, 0)
            current_best = seg.query()
            if current_best > ans:
                ans = current_best
            # Revert
            for i in indices:
                seg.update(i, nums[i])
        return ans

class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1

        # Candidate target frequencies: 1, n, and all distinct non-zero counts
        candidates = {1, n}
        for c in cnt:
            if c > 0:
                candidates.add(c)
        candidates = sorted(candidates)

        min_ops = float('inf')
        offset = n
        INF = float('inf')

        for f in candidates:
            # DP over 26 letters: dp[carry][active] = min cost
            # carry from -n to n, offset by n
            # active: 0 (no f yet), 1 (at least one f)
            dp = [[INF, INF] for _ in range(2 * n + 1)]
            dp[offset][0] = 0

            for i in range(26):
                c = cnt[i]
                new_dp = [[INF, INF] for _ in range(2 * n + 1)]
                for carry_idx in range(2 * n + 1):
                    cur_carry = carry_idx - offset
                    for active in (0, 1):
                        cur_cost = dp[carry_idx][active]
                        if cur_cost == INF:
                            continue

                        # Option 1: t[i] = 0
                        new_carry1 = cur_carry - c
                        if -n <= new_carry1 <= n:
                            new_idx1 = new_carry1 + offset
                            if cur_cost + c < new_dp[new_idx1][active]:
                                new_dp[new_idx1][active] = cur_cost + c

                        # Option 2: t[i] = f
                        if f >= c:
                            if cur_carry > 0:
                                # Use positive carry to cover deficit
                                used = min(cur_carry, f - c)
                                cost2 = (f - c) - used
                                # Each unit of used carry saves 1 operation
                                new_carry2 = cur_carry - used
                            else:
                                cost2 = f - c
                                new_carry2 = cur_carry
                        else:
                            # c > f: we have excess
                            # We can delete or change to right
                            # The excess adds to carry
                            cost2 = c - f
                            new_carry2 = cur_carry + (c - f)

                        if -n <= new_carry2 <= n:
                            new_idx2 = new_carry2 + offset
                            new_active = 1
                            if cur_cost + cost2 < new_dp[new_idx2][new_active]:
                                new_dp[new_idx2][new_active] = cur_cost + cost2

                dp = new_dp

            # Get minimum cost among states with active=1
            for carry_idx in range(2 * n + 1):
                if dp[carry_idx][1] < min_ops:
                    min_ops = dp[carry_idx][1]

        return min_ops

from typing import List
from collections import defaultdict

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)

        # Numbers greater than threshold are always isolated
        # because LCM(x, y) >= x > threshold
        isolated = 0
        small_indices = []  # indices of nums[i] <= threshold
        for i, v in enumerate(nums):
            if v > threshold:
                isolated += 1
            else:
                small_indices.append(i)

        m = len(small_indices)
        if m == 0:
            return isolated

        dsu = DSU(m)

        # Map original index -> position in small_indices
        idx_map = {orig_idx: pos for pos, orig_idx in enumerate(small_indices)}

        # Bucket: for each L from 1 to threshold, store positions of numbers that divide L
        buckets = defaultdict(list)

        for pos, orig_idx in enumerate(small_indices):
            a = nums[orig_idx]
            # Enumerate multiples of a up to threshold
            for multiple in range(a, threshold + 1, a):
                buckets[multiple].append(pos)

        # Union all numbers in each bucket
        for L in range(1, threshold + 1):
            group = buckets.get(L)
            if group and len(group) > 1:
                first = group[0]
                for other in group[1:]:
                    dsu.union(first, other)

        # Count distinct roots among small numbers
        roots = set()
        for pos in range(m):
            roots.add(dsu.find(pos))

        return isolated + len(roots)
